using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Freyja.WorldBuilder.Editor;
public static class Audit023 {public static object Main(){var root=GameObject.Find("Island023");var terrain=root.GetComponentInChildren<Terrain>();var buildings=root.transform.Find("Construções — 12 casas e 5 serviços");var rows=buildings.Cast<Transform>().Select(b=>{var bounds=ExternalModelNormalizer.BoundsOf(b.gameObject);var col=b.GetComponent<BoxCollider>();return new{id=b.name,position=new[]{b.position.x,b.position.y,b.position.z},yaw=b.eulerAngles.y,footprint=new[]{col.size.x,col.size.z},visualBounds=new[]{bounds.size.x,bounds.size.y,bounds.size.z},prefab=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(b.gameObject)};}).ToArray();var report=new{scene=root.scene.path,buildings=rows,terrainSize=new[]{160,40,160},terrainOrigin=new[]{-80,-5,-80},compilationFailed=EditorUtility.scriptCompilationFailed};File.WriteAllText("/Users/bruno.duartec/Documents/Projects/Freyja/Artifacts/Island023/inventory.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return new{count=rows.Length,compilationFailed=EditorUtility.scriptCompilationFailed};}}
